fn audit_retained_spring_fixture_uses_selected_node_state() {
        for mode in [
            PreviewSolverMode::DenseScrutiny,
            PreviewSolverMode::SparseInteractive,
        ] {
            let result = run_linear_static_preview_with_mode(request(), mode);
            assert_eq!(result.status.mechanics, "MECHANICS_SOLVED");
            for (node, support, dof) in [("N-140", "NL-140", "uy"), ("N-130", "NL-130-FRIC", "uz")]
            {
                assert_eq!(
                    result_value(&result, &format!("result:disp:node-{node}:{dof}")),
                    result_value(
                        &result,
                        &format!("result:nonlinear-support:support-{support}:{dof}-displacement")
                    )
                );
            }
        }
    }

    fn p5_beam_request() -> LinearStaticPreviewRequest {
        let mut input = cantilever_constant_effort_request(&[], false, Some(350.0));
        input.model.components.clear();
        input.model.load_cases[0].equivalent_static = None;
        input
    }

    fn p5_uniform_request(span: Option<(f64, f64)>) -> LinearStaticPreviewRequest {
        let mut input = p5_beam_request();
        input.model.load_cases[0].primitive_loads.clear();
        input.model.load_cases[0].equivalent_static = Some(EquivalentStaticGenerationInput {
            seismic: None,
            wind: Some(WindGenerationInput {
                pressure: Some(Quantity {
                    value: 100.0 / 0.168,
                    unit: "Pa".into(),
                }),
                shape_factor: Some(Quantity {
                    value: 1.0,
                    unit: "1".into(),
                }),
                direction: Some("global_y".into()),
                exposed_pipe_refs: if span.is_none() {
                    vec!["pipe:P-100".into()]
                } else {
                    vec![]
                },
                exposed_spans: span
                    .map(|(a, b)| vec![exposed_span_input("pipe:P-100", a, b)])
                    .unwrap_or_default(),
            }),
            provenance: Some("independent_p5_invented_uniform_fixture".into()),
        });
        input
    }

    fn p5_close(actual: f64, expected: f64) {
        assert!(
            (actual - expected).abs() <= 0.5001e-6 + expected.abs() * 1e-10,
            "{actual} != {expected}"
        );
    }

fn authored_coordinate_units_preserve_preview_results_and_source() {
        for mode in [
            PreviewSolverMode::default(),
            PreviewSolverMode::DenseScrutiny,
        ] {
            let baseline =
                run_linear_static_preview_with_mode(authored_coordinate_request("m"), mode);
            assert_eq!(baseline.status.mechanics, "MECHANICS_SOLVED");
            for unit in ["m", "mm", "in"] {
                let input = authored_coordinate_request(unit);
                let source_before = format!("{input:?}");
                let result = run_linear_static_preview_with_mode(input.clone(), mode);
                assert_eq!(format!("{input:?}"), source_before);
                assert_eq!(input.model.project.units["length"], unit);
                assert!(!result.accepted_model_state_mutated);
                assert_eq!(result.status, baseline.status);
                assert_eq!(result.model_ref, baseline.model_ref);
                assert_eq!(result.results.len(), baseline.results.len());
                for (actual, expected) in result.results.iter().zip(&baseline.results) {
                    assert_eq!(actual.id, expected.id);
                    assert_eq!(actual.kind, expected.kind);
                    assert_eq!(actual.unit, expected.unit);
                    assert_eq!(actual.entity_ref, expected.entity_ref);
                    assert_eq!(actual.basis_ref, expected.basis_ref);
                    assert_eq!(actual.source_result_refs, expected.source_result_refs);
                    assert_eq!(actual.metadata, expected.metadata);
                    // Results are rounded to six decimals by the existing adapter.
                    assert!(
                        (actual.value - expected.value).abs() <= 1e-6 + expected.value.abs() * 1e-9,
                        "{mode:?}/{unit}/{}: {} != {}",
                        actual.id,
                        actual.value,
                        expected.value
                    );
                }
                assert_eq!(
                    serde_json::to_value(&result.summary).unwrap(),
                    serde_json::to_value(&baseline.summary).unwrap()
                );
            }
        }
    }

fn bend_component_user_multipliers_emit_stress_review_rows() {
        let result = run_linear_static_preview(request());
        let default_row_id = "result:stress:component-C-110:pipe-P-100:end-j:user-multiplier";
        let combination_row_id =
            "result:combination:combination-C-OPER-ALT:stress:component-C-110:pipe-P-100:end-j:user-multiplier";
        let default_row = result
            .results
            .iter()
            .find(|item| item.id == default_row_id)
            .expect("bend user multiplier row should be emitted for adjacent pipe endpoint");
        let combination_row = result
            .results
            .iter()
            .find(|item| item.id == combination_row_id)
            .expect("bend user multiplier row should participate in explicit combinations");

        assert_eq!(result.summary.component_stress_modifier_count, 8);
        assert_eq!(default_row.kind, "component_user_stress_multiplier_review");
        assert_eq!(default_row.entity_ref, "component:C-110");
        assert!(default_row.value > 0.0);
        assert!(default_row
            .source_result_refs
            .contains(&"result:stress:pipe-P-100:end-j:axial-normal".to_string()));
        assert!(default_row
            .source_result_refs
            .contains(&"result:stress:pipe-P-100:end-j:bending-normal-y".to_string()));
        assert!(default_row
            .source_result_refs
            .contains(&"result:stress:pipe-P-100".to_string()));
        let metadata = default_row
            .metadata
            .as_ref()
            .expect("component multiplier row carries recovery metadata");
        assert_eq!(
            metadata.component,
            "user_entered_component_stress_multiplier"
        );
        assert_eq!(metadata.coordinate_system, "component_review");
        assert_eq!(metadata.location, "pipe:P-100:end_j");
        assert!(metadata.basis.contains("user_entered_sif=1.15"));
        assert!(metadata.basis.contains("user_entered_flexibility=1.08"));
        assert!(metadata
            .basis
            .contains("source=invented_user_entered_preview_no_code_table"));
        assert!(metadata
            .basis
            .contains("solver_consumption=mechanics_geometry_only"));
        assert!(metadata
            .sign_convention
            .contains("base frame stiffness unchanged"));

        assert_eq!(
            combination_row
                .basis_ref
                .as_ref()
                .map(|basis| basis.ref_id.as_str()),
            Some("combination:C-OPER-ALT")
        );
        assert!(
            result
                .diagnostics
                .iter()
                .filter(|diagnostic| diagnostic.code == "COMPONENT_STRESS_MULTIPLIER_APPLIED")
                .count()
                >= 4
        );
    }

fn branch_component_user_multipliers_emit_side_specific_stress_review_rows() {
        let result = run_linear_static_preview(request());
        let branch_row_id = "result:stress:component-C-120:pipe-P-110:end-j:user-multiplier";
        let header_row_id = "result:stress:component-C-120:pipe-P-120:end-i:user-multiplier";
        let combination_row_id =
            "result:combination:combination-C-OPER-ALT:stress:component-C-120:pipe-P-120:end-i:user-multiplier";
        let branch_row = result
            .results
            .iter()
            .find(|item| item.id == branch_row_id)
            .expect(
                "branch-side user multiplier row should be emitted for the branch pipe endpoint",
            );
        let header_row = result
            .results
            .iter()
            .find(|item| item.id == header_row_id)
            .expect(
                "header-side user multiplier row should be emitted for the header pipe endpoint",
            );
        let combination_row = result
            .results
            .iter()
            .find(|item| item.id == combination_row_id)
            .expect("branch user multiplier row should participate in explicit combinations");

        assert_eq!(branch_row.kind, "component_user_stress_multiplier_review");
        assert_eq!(branch_row.entity_ref, "component:C-120");
        assert_eq!(header_row.entity_ref, "component:C-120");
        assert!(branch_row.value > 0.0);
        assert!(header_row.value > 0.0);

        let branch_metadata = branch_row
            .metadata
            .as_ref()
            .expect("branch-side multiplier row carries recovery metadata");
        assert_eq!(branch_metadata.coordinate_system, "component_review");
        assert_eq!(branch_metadata.location, "pipe:P-110:end_j");
        assert!(branch_metadata.basis.contains("component_family=branch"));
        assert!(branch_metadata.basis.contains("component_side=branch"));
        assert!(branch_metadata.basis.contains("user_entered_sif=1.31"));
        assert!(branch_metadata
            .basis
            .contains("source=invented_user_entered_branch_modifiers_no_code_table"));

        let header_metadata = header_row
            .metadata
            .as_ref()
            .expect("header-side multiplier row carries recovery metadata");
        assert_eq!(header_metadata.location, "pipe:P-120:end_i");
        assert!(header_metadata.basis.contains("component_family=branch"));
        assert!(header_metadata.basis.contains("component_side=header"));
        assert!(header_metadata.basis.contains("user_entered_sif=1.22"));

        assert_eq!(
            combination_row
                .basis_ref
                .as_ref()
                .map(|basis| basis.ref_id.as_str()),
            Some("combination:C-OPER-ALT")
        );
    }

fn combination_stress_summary_rows_are_skipped_with_diagnostics() {
        let result = run_linear_static_preview(request());

        assert!(!result
            .results
            .iter()
            .any(|item| item.id == "result:combination:combination-C-OPER-ALT:stress:pipe-P-120"));
        assert!(result.diagnostics.iter().any(|item| item.code
            == "COMBINATION_STRESS_SUMMARY_SKIPPED"
            && item
                .affected_refs
                .contains(&"result:stress:pipe-P-120".to_string())));
    }

fn constant_effort_coexists_with_nonlinear_supports_and_nonlinear_field_precedence() {
        // Consuming constant-effort support in a model whose solve also runs
        // the nonlinear active-set loop: both consume the same assembled
        // force vector.
        let mut request = request();
        request
            .model
            .supports
            .iter_mut()
            .find(|support| support.id == "support:CE-120")
            .expect("fixture carries a constant-effort support")
            .restraints = vec!["UY".to_string()];
        let result = run_linear_static_preview(request);
        assert_eq!(result.status.mechanics, "MECHANICS_SOLVED");
        assert!(result
            .results
            .iter()
            .any(|item| item.id == "result:constant-effort-support:support-CE-120:applied-load"));
        assert!(result
            .results
            .iter()
            .any(|item| item.kind == "nonlinear_support_active_set_iteration_count"));
        assert!(!result
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.code == "SUPPORT_CONSTANT_EFFORT_NOT_CONSUMED"));

        // A constant-effort support carrying a nonlinear field keeps the
        // existing nonlinear-path handling: it is neither classified for
        // constant-force consumption nor warned about.
        let mut precedence_request = super::tests::request();
        let nonlinear_template = precedence_request
            .model
            .supports
            .iter()
            .find(|support| support.id == "support:NL-140")
            .expect("fixture carries a nonlinear support")
            .nonlinear
            .clone();
        precedence_request
            .model
            .supports
            .iter_mut()
            .find(|support| support.id == "support:CE-120")
            .expect("fixture carries a constant-effort support")
            .nonlinear = nonlinear_template;
        let result = run_linear_static_preview(precedence_request);
        assert_eq!(result.status.mechanics, "MECHANICS_SOLVED");
        assert!(!result
            .diagnostics
            .iter()
            .any(|diagnostic| diagnostic.code == "SUPPORT_CONSTANT_EFFORT_NOT_CONSUMED"));
        assert!(!result
            .results
            .iter()
            .any(|item| item.id == "result:constant-effort-support:support-CE-120:applied-load"));
    }

fn curved_bend_macro_element_emits_arc_interior_station_results() {
        let mut arc_request = curved_bend_span_request();
        arc_request.model.load_cases[0]
            .primitive_loads
            .push(curved_bend_uniform_weight_load());
        let result = run_linear_static_preview(arc_request);
        assert_eq!(result.status.mechanics, "MECHANICS_SOLVED");
        // The interior-station residual is retired: no station suppression
        // diagnostic fires and all three station grids are emitted.
        assert!(result
            .diagnostics
            .iter()
            .all(|item| !item.id.contains(":interior-stations")));
        let result_ids = result
            .results
            .iter()
            .map(|item| item.id.as_str())
            .collect::<HashSet<_>>();
        for station in ["quarter-1", "midspan", "quarter-3"] {
            for tail in ["axial", "shear-y", "shear-z"] {
                assert!(
                    result_ids
                        .contains(format!("result:force:pipe-P-100:{station}:{tail}").as_str()),
                    "missing arc station force row {station}:{tail}"
                );
            }
            for tail in ["torsion", "bending-y", "bending-z"] {
                assert!(
                    result_ids
                        .contains(format!("result:moment:pipe-P-100:{station}:{tail}").as_str()),
                    "missing arc station moment row {station}:{tail}"
                );
            }
            assert!(
                result_ids
                    .contains(format!("result:stress:pipe-P-100:{station}:axial-normal").as_str()),
                "missing arc station stress row {station}"
            );
        }

        // Independent oracle: the free loaded tip carries exactly the applied
        // nodal force, so the midspan section resultants follow from segment
        // equilibrium on the direct arc.
        let element = curved_bend_direct_element();
        let intensity = [0.0, 0.0, -190.0];
        let node_j_force = [0.0, 1000.0, 0.0, 0.0, 0.0, 0.0];
        let expected = element
            .arc_section_resultants(0.5, node_j_force, intensity)
            .unwrap();
        let midspan_rows = [
            ("result:force:pipe-P-100:midspan:axial", 0),
            ("result:force:pipe-P-100:midspan:shear-y", 1),
            ("result:force:pipe-P-100:midspan:shear-z", 2),
            ("result:moment:pipe-P-100:midspan:torsion", 3),
            ("result:moment:pipe-P-100:midspan:bending-y", 4),
            ("result:moment:pipe-P-100:midspan:bending-z", 5),
        ];
        for (row_id, slot) in midspan_rows {
            let value = result_value(&result, row_id);
            assert!(
                (value - round6(expected[slot])).abs() <= 1.0e-3,
                "midspan station row {row_id} value {value} must match the direct arc segment equilibrium {}",
                expected[slot]
            );
        }
        let station_row = result
            .results
            .iter()
            .find(|item| item.id == "result:force:pipe-P-100:midspan:shear-z")
            .expect("midspan station row present");
        let metadata = station_row.metadata.as_ref().unwrap();
        assert_eq!(metadata.basis, SECTION_RESULTANT_BASIS);
        assert_eq!(metadata.coordinate_system, "element_local");
        assert_eq!(
            metadata.sign_convention,
            CURVED_BEND_SECTION_SIGN_CONVENTION
        );
        // Straight spans use the canonical stiffness-recovery category with
        // detailed section-equilibrium semantics in the sign convention.
        let straight = run_linear_static_preview(request());
        let straight_row = straight
            .results
            .iter()
            .find(|item| {
                item.id.contains(":midspan:") && item.kind == "element_local_shear_force_y"
            })
            .expect("straight midspan station row present");
        let straight_metadata = straight_row.metadata.as_ref().unwrap();
        assert_eq!(
            straight_metadata.basis,
            "recovered_from_local_element_stiffness"
        );
        assert_eq!(straight_metadata.coordinate_system, "element_local");
    }

fn curved_bend_macro_span_pressure_reaches_nonlinear_loop_with_same_vector() {
        let mut request = curved_bend_span_request();
        request.model.load_cases[0]
            .primitive_loads
            .push(curved_bend_pressure_load());
        request.model.supports.push({
            let mut support = request.model.supports[0].clone();
            support.id = "support:S-110".to_string();
            support.node = "node:N-110".to_string();
            support.restraints = vec![];
            support.nonlinear = Some(NonlinearSupportInput {
                behavior: "one_way".to_string(),
                dof: "UY".to_string(),
                initial_state: Some("inactive".to_string()),
                active_when: Some("positive".to_string()),
                contact_when: None,
                closes_when: None,
                gap: None,
                friction_coefficient: None,
                normal_reaction: None,
                normal_reaction_source: None,
            });
            support
        });
        let result = run_linear_static_preview(request);

        assert_eq!(result.status.mechanics, "MECHANICS_SOLVED");
        assert!(result
            .diagnostics
            .iter()
            .any(|item| item.code == "NONLINEAR_SUPPORT_LOOP_CONVERGED"));
        assert_eq!(
            result_value(&result, "result:nonlinear-support:converged-flag"),
            1.0
        );
        let linear_uy_mm = result_value(&result, "result:disp:node-N-110:uy");
        let nonlinear_uy_mm = result_value(
            &result,
            "result:nonlinear-support:support-S-110:uy-displacement",
        );
        assert!(
            (nonlinear_uy_mm - linear_uy_mm).abs() <= 1.0e-6,
            "nonlinear loop tip displacement {nonlinear_uy_mm} mm must match the linear pressurized macro-span solve {linear_uy_mm} mm"
        );

        // Independent oracle for the combined tip force + complete pressure
        // system on the direct macro element.
        let section = derive_pipe_section(
            &curved_bend_span_request().model.pipe_segments[0].section,
            "pipe:P-100",
            &mut Vec::new(),
        )
        .unwrap();
        let thrust = 2.0e6 * section.internal_area;
        let element = curved_bend_direct_element();
        let [tangent_i, tangent_j] = element.end_tangents().unwrap();
        let mut complete = element
            .consistent_radial_pressure_nodal_loads(thrust)
            .unwrap();
        for axis in 0..3 {
            complete[axis] -= thrust * tangent_i[axis];
            complete[DOF_PER_NODE + axis] += thrust * tangent_j[axis];
        }
        complete[DOF_PER_NODE + UY] += 1000.0;
        let oracle = curved_bend_direct_solution(&complete);
        assert!(
            (linear_uy_mm - round6(oracle[DOF_PER_NODE + UY] * 1000.0)).abs() <= 1.0e-6,
            "pressurized macro-span solve must match the direct oracle"
        );
    }

fn dense_scrutiny_mode_keeps_sparse_parity_row() {
        let result =
            run_linear_static_preview_with_mode(request(), PreviewSolverMode::DenseScrutiny);
        let sparse_evidence = result
            .results
            .iter()
            .find(|item| item.id == "result:sparse-live:dense-parity-relative-delta")
            .expect("dense scrutiny sparse parity row is present");
        let mode_evidence = result
            .results
            .iter()
            .find(|item| item.id == "result:solver-mode:linear-solve-basis")
            .expect("dense scrutiny solver-mode row is present");

        assert_eq!(mode_evidence.value, 2.0);
        assert!(mode_evidence
            .metadata
            .as_ref()
            .unwrap()
            .basis
            .contains("solver_mode=dense_scrutiny"));
        assert_eq!(
            sparse_evidence.kind,
            "sparse_live_path_dense_parity_relative_delta"
        );
        assert!(sparse_evidence.value <= 1.0e-9);
        let metadata = sparse_evidence.metadata.as_ref().unwrap();
        assert_eq!(metadata.component, "sparse_live_path");
        assert!(metadata
            .basis
            .contains("DEC-053 dense_scrutiny_sparse_parity"));
        assert!(metadata.basis.contains("solver_mode=dense_scrutiny"));
        assert!(metadata.basis.contains("sparse_interactive_default=true"));
    }

fn endpoint_section_cut_curved_bend_pressure_shows_membrane_end_and_station_state() {
        let mut request = curved_bend_span_request();
        request.model.load_cases[0].primitive_loads = vec![curved_bend_pressure_load()];
        let section = derive_pipe_section(
            &request.model.pipe_segments[0].section,
            "pipe:P-100",
            &mut Vec::new(),
        )
        .unwrap();
        let thrust = 2.0e6 * section.internal_area;
        let result = run_linear_static_preview(request);
        assert_eq!(result.status.mechanics, "MECHANICS_SOLVED");

        // Membrane end forces: -pA t_i at end i and +pA t_j at end j. The
        // replaced chord frame coincides with the global frame in this
        // fixture, so the chord-frame rows carry the tangent components
        // directly.
        let element = curved_bend_direct_element();
        let [tangent_i, tangent_j] = element.end_tangents().unwrap();
        let force_rows = [
            ("result:force:pipe-P-100:axial", -thrust * tangent_i[0]),
            ("result:force:pipe-P-100:shear-y", -thrust * tangent_i[1]),
            ("result:force:pipe-P-100:shear-z", -thrust * tangent_i[2]),
            ("result:force:pipe-P-100:axial:end-j", thrust * tangent_j[0]),
            (
                "result:force:pipe-P-100:shear-y:end-j",
                thrust * tangent_j[1],
            ),
            (
                "result:force:pipe-P-100:shear-z:end-j",
                thrust * tangent_j[2],
            ),
            ("result:moment:pipe-P-100:torsion", 0.0),
            ("result:moment:pipe-P-100:bending-y", 0.0),
            ("result:moment:pipe-P-100:bending-z", 0.0),
            ("result:moment:pipe-P-100:torsion:end-j", 0.0),
            ("result:moment:pipe-P-100:bending-y:end-j", 0.0),
            ("result:moment:pipe-P-100:bending-z:end-j", 0.0),
        ];
        for (row_id, expected) in force_rows {
            let value = result_value(&result, row_id);
            assert!(
                (value - round6(expected)).abs() <= 1.0e-9 * thrust.max(1.0),
                "end-force row {row_id} value {value} must match the membrane cap force {expected}"
            );
        }

        // Interior stations: axial +pA along the local tangent, zero shear,
        // zero torsion, zero bending at every tested station.
        for station in ["quarter-1", "midspan", "quarter-3"] {
            let axial = result_value(&result, &format!("result:force:pipe-P-100:{station}:axial"));
            assert!(
                (axial - round6(thrust)).abs() <= 1.0e-9 * thrust,
                "station {station} axial {axial} must equal the wall tension {thrust}"
            );
            for row_id in [
                format!("result:force:pipe-P-100:{station}:shear-y"),
                format!("result:force:pipe-P-100:{station}:shear-z"),
                format!("result:moment:pipe-P-100:{station}:torsion"),
                format!("result:moment:pipe-P-100:{station}:bending-y"),
                format!("result:moment:pipe-P-100:{station}:bending-z"),
            ] {
                let value = result_value(&result, &row_id);
                assert!(
                    value.abs() <= 1.0e-9 * thrust,
                    "membrane station row {row_id} must vanish, got {value}"
                );
            }
            let station_stress = result_value(
                &result,
                &format!("result:stress:pipe-P-100:{station}:axial-normal"),
            );
            let expected_stress = round6(thrust / section.area / 1_000_000.0);
            assert!(
                (station_stress - expected_stress).abs() <= 1.0e-6,
                "station {station} axial stress {station_stress} must equal pA / A_s = {expected_stress}"
            );
        }
        let expected_stress = round6(thrust / section.area / 1_000_000.0);
        for location in ["end-i", "end-j"] {
            let row_id = format!("result:stress:pipe-P-100:{location}:axial-normal");
            p5_close(result_value(&result, &row_id), expected_stress);
            let metadata = result
                .results
                .iter()
                .find(|row| row.id == row_id)
                .and_then(|row| row.metadata.as_ref())
                .unwrap();
            assert_eq!(metadata.coordinate_system, "element_local");
            assert_eq!(metadata.basis, SECTION_RESULTANT_BASIS);
            assert_eq!(
                metadata.sign_convention,
                CURVED_BEND_SECTION_SIGN_CONVENTION
            );
        }

        // Tip displacement: closed-form membrane stretch (independent of the
        // flexibility factor) and the direct macro-element oracle under the
        // same complete load system agree with the assembled solve.
        let material = &invented_materials()[0];
        let stretch = thrust / (material.elastic_modulus.value * section.area);
        let expected_ux_mm = round6(stretch * CURVED_BEND_TEST_CHORD_M * 1000.0);
        let ux_mm = result_value(&result, "result:disp:node-N-110:ux");
        let uy_mm = result_value(&result, "result:disp:node-N-110:uy");
        assert!(
            (ux_mm - expected_ux_mm).abs() <= 1.0e-6,
            "membrane tip stretch {ux_mm} mm must match the closed form {expected_ux_mm} mm"
        );
        assert!(
            uy_mm.abs() <= 1.0e-6,
            "membrane state produces no transverse tip displacement, got {uy_mm} mm"
        );
        let wall = element
            .consistent_radial_pressure_nodal_loads(thrust)
            .unwrap();
        let mut complete = wall;
        for axis in 0..3 {
            complete[axis] -= thrust * tangent_i[axis];
            complete[DOF_PER_NODE + axis] += thrust * tangent_j[axis];
        }
        let oracle = curved_bend_direct_solution(&complete);
        assert!(
            (ux_mm - round6(oracle[DOF_PER_NODE + UX] * 1000.0)).abs() <= 1.0e-6,
            "assembled tip displacement must match the direct oracle under the complete system"
        );

        // Pressure gating semantics preserved: the active thrust suppresses
        // the separate longitudinal-pressure stress row while the hoop row
        // remains.
        let result_ids = result
            .results
            .iter()
            .map(|item| item.id.as_str())
            .collect::<HashSet<_>>();
        assert!(result_ids.contains("result:stress:pipe-P-100:end-i:pressure-hoop"));
        assert!(!result_ids.contains("result:stress:pipe-P-100:end-i:pressure-longitudinal"));
        assert!(!result
            .diagnostics
            .iter()
            .any(|item| item.code == "PRESSURE_LOAD_NOT_APPLIED_TO_FRAME_VECTOR"));
    }

    // Nonlinear parity: the same assembled force vector (complete arc
    // pressure system included) reaches the active-set loop, so the
    // released nonlinear solve reproduces the linear macro-span solve of
    // the identical pressurized model exactly.

fn endpoint_section_cut_curved_endpoints_use_all_six_arc_resultants() {
        let mut request = curved_bend_span_request();
        request.model.load_cases[0]
            .primitive_loads
            .push(curved_bend_uniform_weight_load());
        request.model.load_cases[0]
            .primitive_loads
            .push(curved_bend_pressure_load());
        let derived = derive_pipe_section(
            &request.model.pipe_segments[0].section,
            "pipe:P-100",
            &mut Vec::new(),
        )
        .unwrap();
        let result = run_linear_static_preview(request);
        assert_eq!(result.status.mechanics, "MECHANICS_SOLVED");

        let row_ids = [
            "result:force:pipe-P-100:axial",
            "result:force:pipe-P-100:shear-y",
            "result:force:pipe-P-100:shear-z",
            "result:moment:pipe-P-100:torsion",
            "result:moment:pipe-P-100:bending-y",
            "result:moment:pipe-P-100:bending-z",
        ];
        let mut corrected = vec![0.0; ELEMENT_DOF];
        for (slot, row_id) in row_ids.iter().enumerate() {
            corrected[slot] = result_value(&result, row_id);
            corrected[DOF_PER_NODE + slot] = result_value(&result, &format!("{row_id}:end-j"));
        }
        let material = &invented_materials()[0];
        let pipe_section = StraightPipeSectionProperties::new(
            material.elastic_modulus.value,
            material
                .shear_modulus
                .as_ref()
                .expect("validated material G")
                .value,
            derived.area,
            derived.second_moment,
            derived.second_moment,
            derived.torsion_constant,
            None,
        )
        .unwrap();
        let pipe = StraightPipeElement::new(
            "pipe:P-100",
            FrameNode::new(0, [0.0, 0.0, 0.0]).unwrap(),
            FrameNode::new(1, [CURVED_BEND_TEST_CHORD_M, 0.0, 0.0]).unwrap(),
            pipe_section,
            [0.0, 1.0, 0.0],
        )
        .unwrap();
        let build = curved_bend_direct_build();
        let intensity = [0.0, 0.0, -190.0];
        let pressure = 2.0e6;
        let pressure_thrust = pressure * derived.internal_area;
        let node_j_force: [f64; DOF_PER_NODE] = corrected[DOF_PER_NODE..]
            .try_into()
            .expect("six j-end action slots");

        // The public endpoint rows stay the chord-frame node-on-element
        // actions. Reconstruct that independent direct solve before testing
        // the separate arc section-cut resultants consumed by stress.
        let uniform_equivalent = build
            .macro_element
            .consistent_uniform_nodal_loads(intensity)
            .unwrap();
        let radial_equivalent = build
            .macro_element
            .consistent_radial_pressure_nodal_loads(pressure_thrust)
            .unwrap();
        let [tangent_i, tangent_j] = build.macro_element.end_tangents().unwrap();
        let mut applied = [0.0; ELEMENT_DOF];
        for slot in 0..ELEMENT_DOF {
            applied[slot] = uniform_equivalent[slot] + radial_equivalent[slot];
        }
        for axis in 0..3 {
            applied[axis] -= pressure_thrust * tangent_i[axis];
            applied[DOF_PER_NODE + axis] += pressure_thrust * tangent_j[axis];
        }
        applied[DOF_PER_NODE + UY] += 1000.0;
        let displacements = curved_bend_direct_solution(&applied);
        let stiffness = build.macro_element.global_stiffness().unwrap();
        let mut expected_raw = [0.0; ELEMENT_DOF];
        for row in 0..ELEMENT_DOF {
            for col in 0..ELEMENT_DOF {
                expected_raw[row] += stiffness[row][col] * displacements[col];
            }
            expected_raw[row] -= uniform_equivalent[row] + radial_equivalent[row];
            assert!(
                (corrected[row] - round6(expected_raw[row])).abs() <= 1.1e-6,
                "raw chord-frame action slot {row}: {} != {}",
                corrected[row],
                round6(expected_raw[row])
            );
        }
        for row_id in &row_ids {
            for (id, location) in [
                ((*row_id).to_string(), "end_i"),
                (format!("{row_id}:end-j"), "end_j"),
            ] {
                let metadata = result
                    .results
                    .iter()
                    .find(|row| row.id == id)
                    .and_then(|row| row.metadata.as_ref())
                    .unwrap();
                assert_eq!(metadata.location, location);
                assert_eq!(metadata.coordinate_system, "element_local");
                assert_eq!(metadata.basis, SECTION_RESULTANT_BASIS);
                assert!(metadata.sign_convention.contains("force vector"));
            }
        }

        for (fraction, location) in [(0.0, "end-i"), (1.0, "end-j")] {
            let actual = curved_bend_section_resultants(
                &build,
                &pipe,
                &corrected,
                intensity,
                pressure_thrust,
                fraction,
            )
            .unwrap();
            let expected = build
                .macro_element
                .arc_section_resultants_with_radial_pressure(
                    fraction,
                    node_j_force,
                    intensity,
                    pressure_thrust,
                )
                .unwrap();
            for slot in 0..6 {
                assert!(
                    (actual[slot] - expected[slot]).abs() <= 1.0e-9 * expected[slot].abs().max(1.0),
                    "{location} resultant slot {slot}: {} != {}",
                    actual[slot],
                    expected[slot]
                );
            }
            let recovered = recover_section_stress(&actual, &derived, Some(pressure));
            let expected_stresses = [
                ("axial-normal", recovered.components.axial_normal.unwrap()),
                (
                    "bending-normal-y",
                    recovered.components.bending_normal_y.unwrap(),
                ),
                (
                    "bending-normal-z",
                    recovered.components.bending_normal_z.unwrap(),
                ),
                (
                    "torsional-shear",
                    recovered.components.torsional_shear.unwrap(),
                ),
            ];
            for (tail, expected_pa) in expected_stresses {
                p5_close(
                    result_value(
                        &result,
                        &format!("result:stress:pipe-P-100:{location}:{tail}"),
                    ),
                    expected_pa / 1.0e6,
                );
            }
            let metadata = result
                .results
                .iter()
                .find(|row| row.id == format!("result:stress:pipe-P-100:{location}:axial-normal"))
                .and_then(|row| row.metadata.as_ref())
                .unwrap();

fn endpoint_section_cut_genuine_pressure_preserves_existing_result_leaves() {
        let request =
            endpoint_section_cut_pressure_request(&[("load:L-PRESSURE", "pressure", 1_000_000.0)]);
